import sys
from collections import deque
lines = sys.stdin.read().splitlines()
out = []
if lines:
    m = int(lines[0])
    dq = deque()
    for line in lines[1:1+m]:
        cmd = line.split()
        if not cmd: continue
        t = int(cmd[1])
        if cmd[0] == 'HIT': dq.append(t)
        elif cmd[0] == 'GET':
            while dq and dq[0] <= t - 300: dq.popleft()
            out.append(str(len(dq)))
print(' '.join(out))
